function login(){}

function gets_key() {
    var servers = String(source.bookSourceUrl);
    const serverList = servers.split('\n');

    for (let server of serverList) {
        let key = String(cookie.getCookie(server)) || String(java.getCookie(server));
        if (key) {
            let keyParts = key.split('secretKey=');
            if (keyParts.length > 1) {
                key = keyParts[keyParts.length - 1];
                setArgument('key', key);
                return key;
            }
        }
    }

    return '';  
 }

// 填写密钥
function loginqt(){
    let key = gets_key()
    if (key && key != "") {
            java.toast("您已填写秘钥:"+key);
            return false
        }
    java.startBrowserAwait(getArgument('server')+'/check_key','登录晴天小说书源');
    key = gets_key()
    if (key){
        java.longToast('登录成功，秘钥：'+key);
        return true
        } else {
            java.toast('登录失败！！！！！');
            return false
            }
}

//登录番茄
function fq_login() {
    var cookies = cookie.getCookie('fanqienovel.com') || java.getCookie('fanqienovel.com')
    java.log(cookies)
    if (cookies && cookies != "") {
        java.toast("请不要重复登录，请先退出登录！")
        return false
    }
    try {
        java.startBrowserAwait("https://fanqienovel.com/", "登录")
    } catch (e) {
        java.toast(e)
    }
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {}
    var cookies = cookie.getCookie("fanqienovel.com")
    if (!cookies || cookies == "") {
        java.toast("登录失败！")
        return false
    }
    java.toast("登录成功！")
    return true
}

//退出番茄
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
 //cookie.removeCookie(getArgument('server'));
    java.toast("退出登录成功");
}

//获取参数
function getArgument(key) {
    let open_argument = source.getVariable();
    open_argument = getArguments(open_argument,'');
    return open_argument[key];
}

//设置参数
function setArgument(key, value) {
    let open_argument = source.getVariable();
    open_argument = getArguments(open_argument,'');
    open_argument[key] = value;
    open_argument = JSON.stringify(open_argument);
    source.setVariable(open_argument);
    return open_argument;
}

//首页
function api() {     java.startBrowserAwait(getArgument('server')+'/',"接口文档");
    }
//打赏
function vip() {     java.startBrowserAwait(getArgument('server')+'/coffee',"喝咖啡");
    }
//获取密钥
function hqmy() {     java.startBrowserAwait(getArgument('server')+'/key',"获取密钥");
    }

var server = getArgument('server');

//设置搜索媒体
function set_media(media) {
	  setArgument('media',media);
	  java.toast("\n\n已切换至："+media+'\n请重新搜索书籍！');
}

//获取搜索媒体
function get_media() {
	   	let media = getArgument('media');
	   	if(media == '') {
	   		media = '全部来源都搜索';
	   		}
			  java.toast("\n\n当前搜索范围是："+media);

}

//获取服务器
function get_server() {
    var server = getArgument('server');
    var tishi = '\n\n当前服务器：'+ server
    java.toast(tishi);
    return server
}


//设置服务器
function set_server() {
    var servers = String(source.bookSourceUrl);
    const serverList = servers.split('\n');
    const currentIndex = serverList.indexOf(getArgument('server'));
    const nextIndex = (currentIndex + 1) % serverList.length;
    server = serverList[nextIndex];
    setArgument('server',server);
    java.toast('\n\n'+server + '\n\n注意：切换服务器后需要在详情页刷新目录才能生效');
}


//获取音色
var tone_id = getArgument('tone_id');
function get_tone_id(arg) {
      var datadist = {
      	     "0": "默认音色",
            "-1": "阅读模式",
            "-2": "漫画模式",
            "51": "多人发音",
            "1": "甜美少女",
            "2": "清亮青叔",
            "5": "开朗青年",
            "6": "温柔淑女",
            "4": "成熟大叔",
            "74": "大叔升级",
            "30":"优雅御姐"
      };
    var tone_id = datadist[arg] || arg;
    var tishi = '\n\n当前音色：'+ tone_id;    java.toast(tishi);
}

//设置音色
function set_tone_id(mode,name) {
	    	   let toast = "\n\n已切换至：" + name+'\n\n切换后需要刷新详情页';
       setArgument('tone_id',mode);
        java.toast(toast);
    }
