var Headers = JSON.parse(cache.get(Get('url') + "headers"));
var Option = {
    "method": "GET",
    "headers": Headers
};
function test(e) {
    if (e == undefined) {
        return java.log('\n' + JSON.stringify($$$['urls'], null, '\t')) + login('【源站输出提示】' + n(2) + '源站已打印完毕，请到日志查看');
    }
    if (e == 0) {
        login('【初始化提示】' + n(2) + '已恢复默认设置');
        return put(original);
    }
    date1 = new Date().getTime();
    html = java.ajax($$$.urls[e]);
    date2 = new Date().getTime();
    t = date2 - date1;
    time = t / 1000 + 's';
    c = String(html).indexOf('我的');
    logTime = '【' + name(e) + '】\n┋┋\n' + '解析时间：' + time;
    if (c == -1 || t > 5000) {
        return login('【访问失败提示】' + n(2) + '┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️源站已失效(可能被墙)♣️\n┋┋\n请更新网址/切换源站/切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    } else if (t < 1000) {
        return login('【网络环境优良】' + n(2) + '┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n❤️延迟低，推荐使用此站❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    } else if (t >= 1000 && t < 2000) {
        return login('【网络环境一般】' + n(2) + '┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他源站或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    } else if (t >= 2000 && t < 5000) {
        return login('【网络环境堪忧】' + n(2) + '┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他源站或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    }
}
function put(data) {
    return source.setVariable(JSON.stringify(data, null, '\t'));
}
function update() {
    html = java.ajax(fburl);
    J = org.jsoup.Jsoup.parse(html);
    u = J.select('.flex.flex-col.mt-2 a');
    for (i in u) {
        host = String(u[i].attr('href'));
        if (String($$$['urls']).indexOf(host) === -1) {
            java.log('\n✅已添加源站：\n' + host);
            $$$['urls'].push(host);
            put($$$);
        }
    }
    return login('【源站更新提示】' + n(2) + '源站更新完毕，请到日志查看');
}
function name(e) {
    if (e == undefined) {
        e = 0;
    }
    return x[e] + ' ' + $$$.urls[e];
}
function login(e) {
    if (e == undefined) {
        return;
    }
    java.longToast(e);
}
function n(e) {
    n = '\n';
    for (m = 1; m < e; m++) {
        n = n + '\n';
    }
    return n;
}
function k(e) {
    k = ' ';
    for (q = 1; q < e; q++) {
        k = k + ' ';
    }
    return k;
}
function l(e) {
    l = '';
    for (o = 1; o < e; o++) {
        l = l + '';
    }
    return l;
}
function look(e) {
    if (e == 0) {
        return login('【查看当前源站】\n\n┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋' + ('\n ' + '📌' + name($$$.ci0)) + '\n┋┋' + ('\n🔍繁体搜索：' + ($$$.search_TC == true ? '开启' : '关闭')) + '\n┋┋' + ('\n📑简繁转换：' + ($$$.TC_to_SC == false ? '关闭' : '开启')) + '\n┋┋' + ('\n🗃目录整理：' + ($$$.settle == false ? '关闭' : '开启')) + '\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    } else {
        return login('【查看历史接口】\n\n┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋' + ('\n ci1：' + name($$$.ci1)) + '\n┋┋' + ('\n ci2：' + name($$$.ci2)) + '\n┋┋' + ('\n ci3：' + name($$$.ci3)) + '\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛');
    }
}
function $(e) {
    if (e == undefined) {
        e = result['序号：'];
        e = e > 0 ? e : '0';
    }
    if (/^ci[123]$/.test(e)) {
        eval('i=$$$.' + e);
    }
    if (/\D|^$/.test(e) || e < 0 || e >= $$$['urls'].length) {
        return login('【源站错误提示】' + n(2) + '已选择的源站无效，请重新选择');
    }
    $$$['url'] = $$$['urls'][e];
    $$$['ci3'] = $$$['ci2'];
    $$$['ci2'] = $$$['ci1'];
    $$$['ci1'] = $$$['ci0'];
    $$$['ci0'] = e;
    put($$$);
    test(e);
}
function search_TC() {
    if (search_TC == undefined) {
        search_TC = true;
    }
    if ($$$.search_TC == true) {
        login('【繁体搜索提示】' + n(2) + '已关闭繁体搜索，请重新搜索');
        $$$.search_TC = false;
        put($$$);
    } else {
        login('【繁体搜索提示】' + n(2) + '已开启繁体搜索，请重新搜索');
        $$$.search_TC = true;
        put($$$);
    }
}
function TC_to_SC() {
    if (TC_to_SC == undefined) {
        TC_to_SC = true;
    }
    if ($$$.TC_to_SC == true) {
        login('【简繁转换提示】' + n(2) + '已关闭繁体转换，请刷新书籍');
        $$$.TC_to_SC = false;
        put($$$);
    } else {
        login('【简繁转换提示】' + n(2) + '已开启繁体转换，请刷新书籍');
        $$$.TC_to_SC = true;
        put($$$);
    }
}
function settle() {
    if (settle == undefined) {
        settle = true;
    }
    if ($$$.settle == true) {
        login('【目录整理提示】' + n(2) + '已关闭目录整理，请刷新目录');
        $$$.settle = false;
